import { spawnSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { makeTempDir, repositoryRoot } from "./helpers.ts";

// The UC1 pre-registration's detectable-difference block is generated by power.py. These tests keep
// the committed block and the script in step, so an edit to either side fails CI.
const SCRIPT = join(repositoryRoot, "docs", "uc1-preregistration", "power.py");
const DOC = join(repositoryRoot, "docs", "uc1-preregistration.md");
const TIMEOUT_MS = 120_000;

function check(args: readonly string[]): { status: number | null; stdout: string; stderr: string } {
  const result = spawnSync("uv", ["run", "--no-project", "--python", "3.12", "python", SCRIPT, "--check", ...args], {
    cwd: repositoryRoot,
    encoding: "utf8",
  });
  return { status: result.status, stdout: result.stdout, stderr: result.stderr };
}

function copyWith(replace: (text: string) => string): string {
  const path = join(makeTempDir("uc1-preregistration"), "uc1-preregistration.md");
  writeFileSync(path, replace(readFileSync(DOC, "utf8")));
  return path;
}

describe("UC1 pre-registration power.py --check", () => {
  it(
    "passes its reference checks and matches the committed block",
    () => {
      const result = check([]);
      expect(result.stderr).toBe("");
      expect(result).toMatchObject({ status: 0, stdout: "power: uc1-preregistration.md matches the generated block\n" });
    },
    TIMEOUT_MS,
  );

  it(
    "exits 1 when one number in the doc's block is changed",
    () => {
      const original = "| 0% | 32 (0.817) | 42 (0.804) |";
      expect(readFileSync(DOC, "utf8")).toContain(original);
      const tampered = copyWith((text) => text.replace(original, "| 0% | 25 (0.817) | 42 (0.804) |"));
      const result = check(["--doc", tampered]);
      expect(result.status).toBe(1);
      expect(result.stderr).toContain("is missing or differs");
    },
    TIMEOUT_MS,
  );

  it(
    "exits 1 when the doc has no generated block",
    () => {
      const stripped = copyWith((text) => text.replace("<!-- END GENERATED -->", ""));
      const result = check(["--doc", stripped]);
      expect(result.status).toBe(1);
      expect(result.stderr).toContain("is missing or differs");
    },
    TIMEOUT_MS,
  );
});
